    Z('13.2', 1, 'Które mieszaniny (I–IV, schemat w arkuszu) są roztworami buforowymi?', 'II i III', 'Bufor: słaby kwas i sprzężona zasada (np. NH₄Cl + NH₃, NaH₂PO₄ + Na₂HPO₄).'),
    Z('14.1', 2, 'Zmieszano 40 cm³ 0,8 M HCl i 100 cm³ 0,2 M Ba(OH)₂. Oblicz pH (do 0,01).', 'pH ≈ 12,76', 'H⁺ 0,032; OH⁻ 0,04; nadmiar 0,008 mol w 0,14 dm³ → 0,057 M → pOH 1,24.'),
