    Z('18.2', 1, 'Zapisz reakcję w probówce III (kompleks o liczbie koordynacyjnej 4).', 'Zn²⁺ + 4OH⁻ → [Zn(OH)₄]²⁻', '—'),
    Z('19', 1, 'Opisz obserwacje: Na₂SO₃ z fenoloftaleiną (I) i Na₂SO₃ z HCl (II).', 'I: malinowe zabarwienie; II: wydziela się gaz o duszącym zapachu', '—'),
