    Z('35.2', 1, 'Czy trehaloza daje próbę Trommera (I) i czy daje ją po hydrolizie (II)?', 'I — nie (oba węgle anomeryczne w wiązaniu glikozydowym); II — tak (powstaje glukoza)', '—'),
    Z('36', 1, 'Uzupełnij reakcję bezwodnika octowego z kwasem salicylowym (aspiryna).', '(CH₃CO)₂O + HO–C₆H₄–COOH → CH₃COO–C₆H₄–COOH + CH₃COOH', '—'),
